      \sceldas_X_var_reg[2]\ => out_cell_x_counter(2),
      \sceldas_Y_var_reg[0]\ => out_cell_y_counter(0),
      \sceldas_Y_var_reg[1]\ => out_cell_y_counter(1)
    );
end STRUCTURE;
